package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                         // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)    // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 = 0                             // PIC 99 len=2 = 0
var WsCount int64 = 0                              // PIC 99 len=2 = 0
var WsFEd string                                   // PIC ZZ9.9 len=5
var WsCEd string                                   // PIC -ZZ9.99 len=7

var curTempRec TempRec
var scanner *bufio.Scanner

func main() {
	MainPara()
}

// ---------- helpers ----------

func parsePic9V(s string, scale int) decimal.Decimal {
	// s is display numeric field digits only, maybe padded with spaces
	// scale = implied decimal places
	clean := strings.ReplaceAll(s, " ", "")
	clean = strings.TrimSpace(clean)
	if clean == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits (and sign if any)
	digits := ""
	for _, ch := range clean {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	n, err := strconv.ParseInt(digits, 10, 64)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return decimal.New(n, int32(-scale))
}

func storeField(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if d.Sign() == 0 {
		return decimal.NewFromInt(0)
	}
	powInt := int64(1)
	for i := 0; i < intDigits; i++ {
		powInt *= 10
	}
	powScale := int64(1)
	for i := 0; i < scale; i++ {
		powScale *= 10
	}
	abs := d.Abs()
	totalScaled := abs.Mul(decimal.NewFromInt(powScale)).Round(0)
	totalInt := totalScaled.IntPart()
	intPart := totalInt / powScale
	fracPart := totalInt % powScale
	intMod := intPart % powInt
	reconInt := intMod*powScale + fracPart
	recon := decimal.New(reconInt, int32(-scale))
	if d.Sign() < 0 {
		recon = recon.Neg()
	}
	return recon
}

func formatEdited(d decimal.Decimal, intDigits int, fracDigits int, hasSign bool) string {
	powScale := int64(1)
	for i := 0; i < fracDigits; i++ {
		powScale *= 10
	}
	powInt := int64(1)
	for i := 0; i < intDigits; i++ {
		powInt *= 10
	}
	signChar := byte(' ')
	if hasSign {
		if d.Sign() < 0 {
			signChar = '-'
		} else {
			signChar = ' '
		}
	}
	abs := d.Abs()
	totalScaled := abs.Mul(decimal.NewFromInt(powScale)).Round(0).IntPart()
	intPart := totalScaled / powScale
	fracPart := totalScaled % powScale
	intPart = intPart % powInt
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	fracStr := fmt.Sprintf("%0*d", fracDigits, fracPart)

	zCount := intDigits - 1 // last integer position is 9, rest Z
	b := []byte(intStr)
	suppressing := true
	for i := 0; i < intDigits; i++ {
		if i < zCount {
			if suppressing && b[i] == '0' {
				b[i] = ' '
			} else {
				suppressing = false
			}
		}
	}
	intFormatted := string(b)
	if hasSign {
		return string([]byte{signChar}) + intFormatted + "." + fracStr
	}
	return intFormatted + "." + fracStr
}

// ---------- paragraphs ----------

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		WsEofFlag = "Y"
		fmt.Printf("READINGS: %02d BELOW ZERO: %02d\n", WsCount, WsFreeze)
		return
	}
	defer f.Close()
	scanner = bufio.NewScanner(f)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	fmt.Printf("READINGS: %02d BELOW ZERO: %02d\n", WsCount, WsFreeze)
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 8 {
			line = line + strings.Repeat(" ", 8-len(line))
		} else if len(line) > 8 {
			line = line[:8]
		}
		curTempRec.TcSensor = line[0:4]
		tfStr := line[4:8]
		curTempRec.TcF = parsePic9V(tfStr, 1)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	diff := curTempRec.TcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	div := mul.Div(decimal.NewFromInt(9))
	rounded := div.Round(2)
	WsC = storeField(rounded, 3, 2)
	if WsC.Cmp(decimal.NewFromInt(0)) < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatEdited(curTempRec.TcF, 3, 1, false)
	WsCEd = formatEdited(WsC, 3, 2, true)
	fmt.Printf("%s %sF %sC\n", curTempRec.TcSensor, WsFEd, WsCEd)
	ReadPara()
}
